import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { roundCents } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

function calculateLineDiscount(line) {
  const total = lineTotal(line);
  const firstDiscount = roundCents(total * (line.discountPercent ?? 0) / 100);
  const amountAfterFirstDiscount = total - firstDiscount;
  let bulkDiscount = 0;
  if (line.qty >= 10) {
    bulkDiscount = roundCents(amountAfterFirstDiscount * 0.025);
  }
  return firstDiscount + bulkDiscount;
}

function totalPaid(invoice) {
  if (!invoice.payments || !Array.isArray(invoice.payments)) {
    return 0;
  }
  return invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
}

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, dueDate?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number, date: string }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customer = getCustomer(invoice.customerId);
  const customerName = customer.ok ? customer.value.name : 'Unknown Customer';

  const header = invoice.number || 'DRAFT';
  const totals = invoiceTotals(invoice);

  const lines = [header, customerName];

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qtyDisplay = `${line.qty}x`;
    const unitPriceDisplay = formatEuros(line.unitPrice);
    const totalDisplay = formatEuros(total);
    const lineText = `${qtyDisplay} ${line.name.padEnd(30)} ${unitPriceDisplay.padStart(8)}  ${totalDisplay.padStart(8)}`;
    lines.push(lineText);

    const lineDiscount = calculateLineDiscount(line);
    if (lineDiscount > 0) {
      lines.push(`  Discount: -${formatEuros(lineDiscount)}`);
    }
  }

  if (totals.discount > 0 || totals.vat > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
  }

  if (totals.discount > 0) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  const paid = totalPaid(invoice);
  if (paid > 0) {
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

