  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  // header + customer + 1 line item + subtotal + discount (bulk) + vat + total
  assert.equal(lines.length, 7);
  assert.match(result, /100x/);
});

test('renderInvoiceText with multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'COPY-HOUR', qty: 1, discountPercent: 0 },
