test('renderInvoiceText shows all elements in correct order', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 5 },
    ],
    terms: 'NET30',
  }).value;

  const inv = applyVoucher(draft, { code: 'SAVE', amount: 500 }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-10' }).value;

  const result = renderInvoiceText(partial);
  const lines = result.split('\n');

  let prevIndex = -1;
  const checkOrder = (keyword) => {
    const idx = lines.findIndex((l) => l.startsWith(keyword));
    assert.ok(idx > prevIndex, `${keyword} should appear after previous elements (found at ${idx}, prev at ${prevIndex})`);
    prevIndex = idx;
  };

  checkOrder('Northwind');
  checkOrder('Subtotal:');
  checkOrder('Discount:');
  checkOrder('VAT:');
  checkOrder('Voucher:');
  checkOrder('Total:');
  checkOrder('Paid:');
  checkOrder('Due:');
});

