  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 5000, date: '2026-10-10' }).value;
  const partial2 = recordPayment(partial1, { amount: 3000, date: '2026-10-15' }).value;

  const result = renderInvoiceText(partial2);
  assert.match(result, /Paid: €80\.00/);
