test('renderInvoiceText calculates correct total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
    ],
  }).value;

  const result = renderInvoiceText(invoice);
  // DES-HOUR: 2 * 8500 = 17000, VAT = 17000 * 21% = 3570
  // DEV-HOUR: 3 * 9500 = 28500, VAT = 28500 * 21% = 5985
  // Total VAT: 9555
  // Total: 45500 + 9555 = 55055 = €550.55
  assert.match(result, /Total: €550\.55/);
});

