test('renderInvoiceText shows full payment amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-10' }).value;

  const result = renderInvoiceText(paid);
  const expectedAmount = (totals.total / 100).toFixed(2);
  assert.match(result, new RegExp(`Paid: €${expectedAmount}`));
});

